import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

const PAST = "2026-01-01T00:00:00.000Z";
const NOW = new Date("2026-06-01T07:00:00.000Z");

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetOverdueTracking();
});

afterAll(() => {
  cleanup();
});

describe("archived project freeze", () => {
  it("blocks writes, keeps reads, and lifts on restore", async () => {
    const tenant = await createTenant("freeze");
    await usageRepo.recomputeUsage(tenant.org.id);
    const actor = tenant.actors.member;

    const issue = await issueService.createIssue(
      actor,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Still live",
        dueAt: PAST,
        assigneeId: tenant.userIds.member,
      }),
    );
    const comment = await commentService.createComment(actor, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "note",
      parentId: null,
      mentionedUserIds: [],
    });
    const attachment = await attachmentService.addAttachment(actor, {
      orgId: tenant.org.id,
      issueId: issue.id,
      filename: "a.txt",
      contentType: "text/plain",
      sizeBytes: 12,
    });

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    const events: string[] = [];
    const off = subscribe("issue.updated", () => events.push("issue.updated"));
    const off2 = subscribe("issue.status_changed", () => events.push("status"));
    const off3 = subscribe("issue.assigned", () => events.push("assigned"));
    const off4 = subscribe("issue.archived", () => events.push("archived"));
    const off5 = subscribe("comment.created", () => events.push("comment.created"));
    const off6 = subscribe("comment.deleted", () => events.push("comment.deleted"));
    const off7 = subscribe("issue.overdue", () => events.push("overdue"));
    const off8 = subscribe("issue.created", () => events.push("created"));

    const writes = [
      issueService.updateIssue(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "changed",
      }),
      issueService.changeIssueStatus(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        status: "in_progress",
      }),
      issueService.moveIssue(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        toStatus: "todo",
        toIndex: 0,
      }),
      issueService.assignIssue(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: tenant.userIds.admin,
      }),
      issueService.assignIssue(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        assigneeId: null,
      }),
      issueService.archiveIssue(actor, tenant.org.id, issue.id),
      commentService.createComment(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "nope",
        parentId: null,
        mentionedUserIds: [],
      }),
      commentService.updateComment(actor, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "edited",
      }),
      commentService.deleteComment(tenant.actors.admin, {
        orgId: tenant.org.id,
        commentId: comment.id,
      }),
      attachmentService.addAttachment(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        filename: "b.txt",
        contentType: "text/plain",
        sizeBytes: 8,
      }),
      attachmentService.removeAttachment(actor, {
        orgId: tenant.org.id,
        attachmentId: attachment.id,
      }),
      issueService.createIssue(
        actor,
        issueInput(tenant.org.id, tenant.project.id, { title: "new" }),
      ),
    ];

    for (const write of writes) {
      await expect(write).rejects.toBeInstanceOf(AlreadyArchivedError);
    }

    await expect(
      issueService.updateIssue(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "viewer",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const loaded = await issueService.getIssue(actor, tenant.org.id, issue.id);
    expect(loaded.issue.title).toBe("Still live");
    expect(loaded.issue.status).toBe("backlog");
    expect(loaded.issue.assigneeId).toBe(tenant.userIds.member);
    expect(loaded.issue.archivedAt).toBeNull();
    expect(loaded.commentCount).toBe(1);
    expect(loaded.attachmentCount).toBe(1);

    const thread = await commentService.getThread(actor, tenant.org.id, issue.id);
    expect(thread).toHaveLength(1);
    expect(thread[0]?.comment.body).toBe("note");

    const files = await attachmentService.listAttachments(actor, tenant.org.id, issue.id);
    expect(files).toHaveLength(1);

    const board = await issueService.getBoard(actor, tenant.org.id, tenant.project.id);
    expect(board.flatMap((column) => column.issues.map((row) => row.id))).toContain(issue.id);

    const listed = await issueRepo.listOverdueIssues(
      tenant.org.id,
      toIsoTimestamp(NOW),
    );
    expect(listed.map((row) => row.id)).not.toContain(issue.id);

    await runOverdueIssueJob(NOW);
    expect(events).toEqual([]);

    await projectService.restoreProject(
      tenant.actors.admin,
      tenant.org.id,
      tenant.project.id,
    );

    const updated = await issueService.updateIssue(actor, {
      orgId: tenant.org.id,
      issueId: issue.id,
      title: "thawed",
    });
    expect(updated.title).toBe("thawed");

    await runOverdueIssueJob(NOW);
    expect(events).toContain("overdue");

    off();
    off2();
    off3();
    off4();
    off5();
    off6();
    off7();
    off8();
  });

  it("lets an archived issue report itself ahead of the project", async () => {
    const tenant = await createTenant("freeze-issue");
    const actor = tenant.actors.member;
    const issue = await issueService.createIssue(
      actor,
      issueInput(tenant.org.id, tenant.project.id, { title: "Will archive" }),
    );
    const comment = await commentService.createComment(actor, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "keep",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.archiveIssue(actor, tenant.org.id, issue.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    await expect(
      issueService.updateIssue(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "no",
      }),
    ).rejects.toMatchObject({ entity: "Issue", id: issue.id });

    await commentService.deleteComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      commentId: comment.id,
    });
    const archivedComment = await commentService.createComment(actor, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "should fail on issue",
      parentId: null,
      mentionedUserIds: [],
    }).catch((error: unknown) => error);
    expect(archivedComment).toBeInstanceOf(AlreadyArchivedError);
    expect(archivedComment).toMatchObject({ entity: "Issue", id: issue.id });
  });
});

