input.new_string:
  it("lets an archived issue or comment report itself ahead of the project", async () => {
    const tenant = await createTenant("freeze-issue");
    const actor = tenant.actors.member;
    const issue = await issueService.createIssue(
      actor,
      issueInput(tenant.org.id, tenant.project.id, { title: "Will archive" }),
    );
    const comment = await commentService.createComment(actor, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "keep",
      parentId: null,
      mentionedUserIds: [],
    });
    await issueService.archiveIssue(actor, tenant.org.id, issue.id);

    // A live comment on an archived issue in a live project stays editable.
    const edited = await commentService.updateComment(actor, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "still editable",
    });
    expect(edited.body).toBe("still editable");

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });

    await expect(
      issueService.updateIssue(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "no",
      }),
    ).rejects.toMatchObject({ name: "AlreadyArchivedError", entity: "Issue", id: issue.id });

    await expect(
      commentService.createComment(actor, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "should fail on issue",
        parentId: null,
        mentionedUserIds: [],
      }),
    ).rejects.toMatchObject({ entity: "Issue", id: issue.id });

    await expect(
      commentService.deleteComment(tenant.actors.admin, {
        orgId: tenant.org.id,
        commentId: comment.id,
      }),
    ).rejects.toMatchObject({ entity: "Project", id: tenant.project.id });

    const removed = await commentService.deleteComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      commentId: comment.id,
    }).catch(() => null);
    expect(removed).toBeNull();

    await projectService.restoreProject(
      tenant.actors.admin,
      tenant.org.id,
      tenant.project.id,
    );
    const gone = await commentService.deleteComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      commentId: comment.id,
    });
    await expect(
      commentService.deleteComment(tenant.actors.admin, {
        orgId: tenant.org.id,
        commentId: gone.id,
      }),
    ).rejects.toMatchObject({ entity: "Comment", id: comment.id });
  });
});

